import{_ as s,o as l,c as e,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const D=JSON.parse('{"title":"CDS Infernalis (Day 2.2) -- OSD: Newstore","description":"","frontmatter":{"title":"CDS Infernalis (Day 2.2) -- OSD: Newstore","date":"2015-03-06T00:00:00.000Z","updated":"2015-03-07T00:00:00.000Z","tags":["Ceph","Distributed Storage","OSD","BlueStore","RocksDB"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Newstore.md","filePath":"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Newstore.md","lastUpdated":1780459816000}'),o={name:"posts/2015/CDS_Infernalis_Day_2.2_--_OSD_-_Newstore.md"};function n(i,t,a,_,p,g){return l(),e("div",null,[...t[0]||(t[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： 新存储后端OSD讨论</p><p><strong>会议时间</strong>： 未知</p><p><strong>参会人员</strong>： Sage、其他研发人员</p><p><strong>会议内容</strong>：</p><p><strong>1. 新存储后端OSD的动机和目标</strong></p><p>会议指出，现有文件存储系统经过多年开发，功能复杂，难以修改和优化。因此，目标是创建一个新的内部对象存储接口实现，以替换现有的对象存储，并支持多种后端。新实现将适用于硬盘和SSD，或两者的组合。主要目标是避免对新对象的重复写入和顺序写入，从而消除当前日志记录带来的开销，并提高小写操作的效率。</p><p><strong>2. 新存储后端OSD的技术方案</strong></p><ul><li>使用键值数据库（如RocksDB）进行事务和键值数据管理。</li><li>使用POSIX文件系统（如XFS）进行块管理。</li><li>工作流程： <ul><li>接收写请求，根据请求类型（新对象、追加到现有对象）打开或创建文件，并将数据写入文件。</li><li>使用fsync提交事务，并将文件系统同步到磁盘。</li><li>在fsync完成后，将对象大小或存在性信息提交到键值数据库。</li><li>对于小写操作，使用写前日志（write-ahead log）进行管理。</li></ul></li></ul><p><strong>3. 技术细节和讨论</strong></p><ul><li><strong>同步和异步提交</strong>： 当前实现中，事务提交是同步的，可能会增加延迟。计划改为异步提交，以提高性能。</li><li><strong>写前日志</strong>： 对于小写操作，可以考虑将写前日志项也存储在键值数据库中，以减少磁盘I/O。</li><li><strong>优化</strong>： 可以利用XFS的特性，例如使用open by handle接口，以减少路径遍历。</li><li><strong>测试和评估</strong>： 需要对新存储后端进行基准测试，以评估其性能和效率。</li></ul><p><strong>4. 行动计划</strong></p><ul><li>完成omap的实现。</li><li>将事务提交改为异步。</li><li>对新存储后端进行基准测试。</li><li>考虑使用LMDB作为键值数据库。</li></ul><p><strong>5. 其他讨论</strong></p><ul><li>使用ODIR/O_SYNC进行同步。</li><li>使用检查点方法进行同步。</li><li>使用AIO进行异步I/O。</li></ul><p><strong>总结</strong>：</p><p>本次会议讨论了新存储后端OSD的方案和实施细节，并制定了后续行动计划。该方案旨在提高存储性能和效率，并支持多种后端，包括硬盘和SSD。</p>',17)])])}const d=s(o,[["render",n]]);export{D as __pageData,d as default};
